import re

def parse(lines):
    blocks = {}
    order = []
    skip = []

    def add(name, kind, i, rec):
        if name not in blocks:
            blocks[name] = {'name': name, 'kind': kind, 'lines': [], 'records': []}
            order.append(name)
        b = blocks[name]
        b['lines'].append(i)
        if rec is not None:
            b['records'].append(rec)
        return b

    section = None
    cur_ver = ''
    desc = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = re.match(r'^Package:\s*(.*?)\s*$', l)
        if m:
            b = add('package', 'kv', i, None)
            if not b['records']:
                b['records'].append({})
            b['records'][0]['Package'] = m.group(1)
            section = None
            continue
        m = re.match(r'^(Versions|Reverse Depends|Dependencies|Provides|Reverse Provides):\s*$', l)
        if m:
            section = m.group(1)
            skip.append(i)
            continue
        if section == 'Versions':
            m = re.match(r'^\s*Description Language:\s*(.*?)\s*$', l)
            if m:
                desc = {'Version': cur_ver, 'Description Language': m.group(1), 'File': '', 'MD5': ''}
                add('descriptions', 'table', i, desc)
                continue
            m = re.match(r'^\s+(File|MD5):\s*(.*?)\s*$', l)
            if m and desc is not None:
                desc[m.group(1)] = m.group(2)
                add('descriptions', 'table', i, None)
                continue
            m = re.match(r'^(\S+)\s+\((.*)\)\s*$', l)
            if m:
                cur_ver = m.group(1)
                desc = None
                add('versions', 'table', i, {'Version': m.group(1), 'File': m.group(2)})
                continue
        elif section == 'Reverse Depends':
            m = re.match(r'^\s*([^,\s]+),(\S+)(?:\s+(.*?))?\s*$', l)
            if m:
                add('reverse_depends', 'table', i, {'Package': m.group(1), 'Depends on': m.group(2), 'Version': m.group(3) or ''})
                continue
        elif section in ('Dependencies', 'Provides'):
            m = re.match(r'^\s*(\S+)\s+-\s*(.*?)\s*$', l)
            if m:
                add(section.lower(), 'table', i, {'Version': m.group(1), section: m.group(2)})
                continue
        elif section == 'Reverse Provides':
            m = re.match(r'^\s*(\S+)\s+(\S+)(?:\s+(.*?))?\s*$', l)
            if m:
                add('reverse_provides', 'table', i, {'Package': m.group(1), 'Version': m.group(2), 'Provides': m.group(3) or ''})
                continue
    return {'blocks': [blocks[n] for n in order], 'skip': skip}
